#pragma once

#include "contrib/gpu/src/common/codec_decode_planning.hpp"

namespace openzl::gpu {

/**
 * Plans the numeric stream regenerated by float deconstruction.
 *
 * @p codec supplies the staged one-byte element-type header. @p inputs must
 * contain sign/fraction followed by exponent in decoder order. @p outputs must
 * contain exactly one slot; that slot is unchanged on error.
 *
 * This function validates and derives output properties only.
 *
 * @returns The regenerated output count, which is one, or an error.
 */
ZL_Report planFloatDeconstructOutputs(
        const CodecDecodePlanningContext& codec,
        std::span<const StreamPlanningInput> inputs,
        std::span<CodecDecodeOutputPlan> outputs,
        ZL_OperationContext* opCtx);

} // namespace openzl::gpu
